//! CRX3 developer-proof validation and identity preservation for unpacked WebView2 imports.
use sha2::{Digest,Sha256};
use ring::signature;
use base64::Engine;
pub struct SignedCrx{pub offset:usize,pub id:String,pub key:String}
fn varint(data:&[u8],at:&mut usize)->Result<u64,String>{let mut n=0u64;for i in 0..10{let b=*data.get(*at).ok_or("CRX protobuf eksik")?;*at+=1;if i==9&&b>1{return Err("CRX varint taşması".into());}n|=((b&127)as u64)<<(7*i);if b&128==0{return Ok(n);}}Err("CRX varint geçersiz".into())}
fn fields(data:&[u8])->Result<Vec<(u64,&[u8])>,String>{let mut at=0;let mut out=Vec::new();while at<data.len(){if out.len()>64{return Err("CRX başlığı çok karmaşık".into());}let tag=varint(data,&mut at)?;if tag>>3==0{return Err("CRX alanı geçersiz".into());}match tag&7{0=>{varint(data,&mut at)?;},2=>{let n=usize::try_from(varint(data,&mut at)?).map_err(|_|"CRX alanı çok büyük")?;let end=at.checked_add(n).filter(|n|*n<=data.len()).ok_or("CRX alanı eksik")?;out.push((tag>>3,&data[at..end]));at=end;},1|5=>{at=at.checked_add(if tag&7==1{8}else{4}).filter(|n|*n<=data.len()).ok_or("CRX alanı eksik")?;},_=>return Err("CRX alan türü geçersiz".into())}}Ok(out)}
fn der<'a>(data:&mut &'a[u8],tag:u8)->Result<&'a[u8],String>{if data.first()!=Some(&tag){return Err("CRX anahtar biçimi geçersiz".into());}*data=&data[1..];let b=*data.first().ok_or("CRX anahtarı eksik")?;*data=&data[1..];let n=if b&128==0{b as usize}else{let k=(b&127)as usize;if k==0||k>4||data.len()<k{return Err("CRX DER uzunluğu geçersiz".into());}let mut n=0usize;for v in &data[..k]{n=n.checked_mul(256).and_then(|n|n.checked_add(*v as usize)).ok_or("CRX DER taşması")?;}*data=&data[k..];n};if n>data.len(){return Err("CRX anahtarı eksik".into());}let out=&data[..n];*data=&data[n..];Ok(out)}
fn public_key(spki:&[u8])->Result<&[u8],String>{let mut whole=spki;let mut sequence=der(&mut whole,0x30)?;if !whole.is_empty(){return Err("CRX anahtarı sonunda veri var".into());}der(&mut sequence,0x30)?;let bits=der(&mut sequence,0x03)?;if !sequence.is_empty()||bits.first()!=Some(&0){return Err("CRX anahtarı geçersiz".into());}Ok(&bits[1..])}
pub fn verify(data:&[u8],expected:Option<&str>)->Result<SignedCrx,String>{
 if data.len()<12||&data[..4]!=b"Cr24"||u32::from_le_bytes(data[4..8].try_into().unwrap())!=3{return Err("Yalnız imzalı CRX3 desteklenir. Eski CRX2 yerine güvenilir bir ZIP veya klasör seç.".into());}
 let n=u32::from_le_bytes(data[8..12].try_into().unwrap())as usize;let end=12usize.checked_add(n).filter(|n|*n<=data.len()&&*n<=2*1024*1024).ok_or("CRX başlığı geçersiz")?;
 let header=fields(&data[12..end])?;let signed:Vec<_>=header.iter().filter(|(k,_)|*k==10000).map(|(_,v)|*v).collect();if signed.len()!=1{return Err("CRX imza başlığı eksik veya yinelenmiş".into());}let signed=signed[0];
 let ids:Vec<_>=fields(signed)?.into_iter().filter(|(k,_)|*k==1).map(|(_,v)|v).collect();if ids.len()!=1||ids[0].len()!=16{return Err("CRX kimliği geçersiz".into());}let crx_id=ids[0];
 let id:String=crx_id.iter().flat_map(|b|[(b'a'+(b>>4))as char,(b'a'+(b&15))as char]).collect();if expected.is_some_and(|v|v!=id){return Err("İndirilen paket istenen mağaza eklentisiyle eşleşmiyor".into());}
 let mut message=Vec::with_capacity(data.len()+32);message.extend_from_slice(b"CRX3 SignedData\0");message.extend_from_slice(&(signed.len()as u32).to_le_bytes());message.extend_from_slice(signed);message.extend_from_slice(&data[end..]);
 for(algorithm,proof)in header.into_iter().filter(|(k,_)|*k==2||*k==3){let proof=fields(proof)?;let key:Vec<_>=proof.iter().filter(|(k,_)|*k==1).map(|(_,v)|*v).collect();let signatures:Vec<_>=proof.iter().filter(|(k,_)|*k==2).map(|(_,v)|*v).collect();if key.len()!=1||signatures.len()!=1{continue;}let key=key[0];if &Sha256::digest(key)[..16]!=crx_id{continue;}let raw=public_key(key)?;
  let result=if algorithm==2{signature::UnparsedPublicKey::new(&signature::RSA_PKCS1_2048_8192_SHA256,raw).verify(&message,signatures[0])}else{signature::UnparsedPublicKey::new(&signature::ECDSA_P256_SHA256_ASN1,raw).verify(&message,signatures[0])};
  if result.is_ok(){return Ok(SignedCrx{offset:end,id,key:base64::engine::general_purpose::STANDARD.encode(key)});}
 }Err("CRX geliştirici imzası doğrulanamadı; paket yüklenmedi".into())
}
#[cfg(test)]mod tests{use super::*;use ring::{rand::SystemRandom,signature::{EcdsaKeyPair,KeyPair}};
 fn v(mut n:u64)->Vec<u8>{let mut b=Vec::new();loop{let x=(n&127)as u8;n>>=7;b.push(if n>0{x|128}else{x});if n==0{return b;}}}
 fn field(k:u64,data:&[u8])->Vec<u8>{let mut b=v(k*8+2);b.extend(v(data.len()as u64));b.extend(data);b}
 #[test]fn signature_and_identity(){let random=SystemRandom::new();let der=EcdsaKeyPair::generate_pkcs8(&signature::ECDSA_P256_SHA256_ASN1_SIGNING,&random).unwrap();let pair=EcdsaKeyPair::from_pkcs8(&signature::ECDSA_P256_SHA256_ASN1_SIGNING,der.as_ref(),&random).unwrap();let mut key=vec![0x30,0x59,0x30,0x13,0x06,0x07,0x2a,0x86,0x48,0xce,0x3d,0x02,0x01,0x06,0x08,0x2a,0x86,0x48,0xce,0x3d,0x03,0x01,0x07,0x03,0x42,0];key.extend(pair.public_key().as_ref());let id=Sha256::digest(&key);let signed=field(1,&id[..16]);let zip=b"fixture payload";let mut message=b"CRX3 SignedData\0".to_vec();message.extend((signed.len()as u32).to_le_bytes());message.extend(&signed);message.extend(zip);let signature=pair.sign(&random,&message).unwrap();let mut proof=field(1,&key);proof.extend(field(2,signature.as_ref()));let mut header=field(3,&proof);header.extend(field(10000,&signed));let mut crx=b"Cr24".to_vec();crx.extend(3u32.to_le_bytes());crx.extend((header.len()as u32).to_le_bytes());crx.extend(header);crx.extend(zip);let good=verify(&crx,None).unwrap();assert!(verify(&crx,Some(&good.id)).is_ok());assert!(verify(&crx,Some(&"a".repeat(32))).is_err());*crx.last_mut().unwrap()^=1;assert!(verify(&crx,None).is_err());}
 #[test]fn malformed_headers(){for bytes in [&b"Cr24"[..],&b"Cr24\x03\0\0\0\xff\xff\xff\xff"[..]]{assert!(verify(bytes,None).is_err());}assert!(fields(&[0xff;32]).is_err());}
}
